<?php require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../config/koneksi.php'; require_once __DIR__ . '/../includes/functions.php'; if($_SERVER['REQUEST_METHOD']!=='POST') redirect('anggota.php'); validate_csrf(); $nama=trim($_POST['nama']??''); $jabatan=trim($_POST['jabatan']??''); $kelas=trim($_POST['kelas']??''); if($nama===''||$jabatan==='') die('Nama dan jabatan wajib diisi.'); try{ $foto=upload_image($_FILES['foto']??null,'../uploads/'); db_query($conn,'INSERT INTO anggota_osis (nama,jabatan,kelas,foto) VALUES (?,?,?,?)',[$nama,$jabatan,$kelas,$foto]); redirect('anggota.php'); } catch(Exception $e){ die('Gagal simpan anggota: '.e($e->getMessage())); }
